if(!data.classes.length){root.append(node('div','pj-empty','کلاس فعال و مجازی به این حساب متصل نیست. اطلاعات آموزشی پس از اتصال کلاس نمایش داده می‌شود.'));return;}
const layout=node('div','pj-layout'),side=node('aside','pj-classes'),body=node('div','pj-body');side.setAttribute('aria-label','انتخاب کلاس');const search=node('input');search.type='search';search.placeholder='نام هنرجو، ساز یا استاد…';search.setAttribute('aria-label','جست‌وجوی کلاس');search.value=query;search.oninput=()=>{query=search.value;drawClasses();};side.append(search);
