const c=selectedClass();if(!c){body.append(node('p','','کلاسی را انتخاب کنید.'));return;}const header=node('section','pj-class-header');header.append(node('div'));header.firstChild.append(node('small','','مسیر '+c.first_name+' '+c.last_name),node('h2','',c.subject),node('p','','استاد '+c.teacher_name+' · '+days[c.weekday]+' '+c.class_time.slice(0,5)));if(teaching())header.append(button('＋ ارزیابی بعد از کلاس',()=>reviewForm(),'pj-primary'));body.append(header);
