const timeLabel=v=>{const x=Math.max(0,Math.floor(Number(v)));return String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0');};
async function storage(path,options={}){const user=uid,s=await portalAuth.getSession();if(s.error||!s.data.session)throw Error('ورود دوباره لازم است');const r=await fetch(SUPABASE_ENDPOINT+'/storage/v1/'+path,{...options,headers:{apikey:KEY,Authorization:'Bearer '+s.data.session.access_token,...options.headers}});const result=await r.json().catch(()=>({}));if(user!==uid)throw Error('حساب تغییر کرده است');if(!r.ok){const e=Error(result.message||result.error||'ارتباط با فایل انجام نشد');e.status=r.status;throw e;}return result;}
