function seek(id,value){const a=[...activeMedia].filter(x=>x.dataset.audioId===id&&x.src).at(-1);if(a?.src){a.currentTime=Number(value);a.focus();}else toast('ابتدا بارگذاری امن همین فایل را بزنید.');}
