const score=field(f,'امتیاز آموزشی این جلسه از ۱۰','score',existing?.score??'','number');score.min='1';score.max='10';score.step='1';const rating=node('div','pj-score-picker');for(let i=1;i<=10;i++){const b=button(fmt(i),()=>{score.value=String(i);for(const other of rating.children){const on=other===b;other.classList.toggle('picked',on);other.setAttribute('aria-pressed',String(on));}});b.setAttribute('aria-label','امتیاز '+fmt(i)+' از ۱۰');b.setAttribute('aria-pressed',String(Number(score.value)===i));if(Number(score.value)===i)b.classList.add('picked');rating.append(b);}score.closest('label').after(rating);field(f,'نقاط قوت و پیشرفت این جلسه','strengths',existing?.strengths||'','textarea',false).maxLength=2000;const challenges=field(f,'مشکلات مشخص و نکات نیازمند تمرین','challenges',existing?.challenges||'','textarea');challenges.minLength=3;challenges.maxLength=2000;const practice=field(f,'تمرین دقیق تا جلسه بعد','practice',existing?.practice||'','textarea');practice.minLength=3;const mins=field(f,'مدت پیشنهادی هر نوبت تمرین (دقیقه)','practice_minutes',existing?.practice_minutes??15,'number');mins.min='5';mins.max='120';const due=field(f,'مهلت پیشنهادی ارسال تمرین (شمسی؛ اختیاری)','due_date',existing?.due_date?showDate(existing.due_date):'','text',false);due.placeholder='۱۴۰۵/۰۸/۲۸';const submit=node('button','pj-primary','دیدن پیش‌نمایش ارزیابی');submit.type='submit';f.append(submit);box.append(f);let key=null,last=null;
